CREATE TABLE app_users (id BIGSERIAL PRIMARY KEY, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, username VARCHAR(80) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE roles (name VARCHAR(40) PRIMARY KEY);
CREATE TABLE user_roles (user_id BIGINT NOT NULL REFERENCES app_users(id), role_name VARCHAR(40) NOT NULL REFERENCES roles(name), PRIMARY KEY(user_id,role_name));
CREATE TABLE categories (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, parent_id BIGINT REFERENCES categories(id), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE configuration_items (id BIGSERIAL PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, type VARCHAR(60) NOT NULL, description TEXT, status VARCHAR(40) NOT NULL, location VARCHAR(150), owner_id BIGINT REFERENCES app_users(id), serial_number VARCHAR(100), ip_address VARCHAR(45), manufacturer VARCHAR(100), model VARCHAR(100), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE incidents (id BIGSERIAL PRIMARY KEY, code VARCHAR(40) UNIQUE, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, requester_id BIGINT NOT NULL REFERENCES app_users(id), category_id BIGINT REFERENCES categories(id), impact VARCHAR(20) NOT NULL, urgency VARCHAR(20) NOT NULL, priority VARCHAR(2) NOT NULL, status VARCHAR(30) NOT NULL, assignee_id BIGINT REFERENCES app_users(id), solution TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), assigned_at TIMESTAMPTZ, resolved_at TIMESTAMPTZ, closed_at TIMESTAMPTZ);
CREATE TABLE incident_items (incident_id BIGINT NOT NULL REFERENCES incidents(id), item_id BIGINT NOT NULL REFERENCES configuration_items(id), PRIMARY KEY(incident_id,item_id));
CREATE TABLE incident_history (id BIGSERIAL PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES incidents(id), actor_id BIGINT NOT NULL REFERENCES app_users(id), action VARCHAR(40) NOT NULL, old_value TEXT, new_value TEXT, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE incident_comments (id BIGSERIAL PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES incidents(id), author_id BIGINT NOT NULL REFERENCES app_users(id), content TEXT NOT NULL, visibility VARCHAR(10) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE problems (id BIGSERIAL PRIMARY KEY, code VARCHAR(40) UNIQUE, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, status VARCHAR(30) NOT NULL, priority VARCHAR(2) NOT NULL, owner_id BIGINT REFERENCES app_users(id), root_cause TEXT, workaround TEXT, permanent_solution TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ);
CREATE TABLE problem_incidents (problem_id BIGINT NOT NULL REFERENCES problems(id), incident_id BIGINT NOT NULL REFERENCES incidents(id), PRIMARY KEY(problem_id,incident_id));
CREATE TABLE problem_items (problem_id BIGINT NOT NULL REFERENCES problems(id), item_id BIGINT NOT NULL REFERENCES configuration_items(id), PRIMARY KEY(problem_id,item_id));
CREATE TABLE known_errors (id BIGSERIAL PRIMARY KEY, code VARCHAR(40) UNIQUE, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, symptoms TEXT, known_cause TEXT, workaround TEXT, permanent_solution TEXT, status VARCHAR(30) NOT NULL, problem_id BIGINT NOT NULL REFERENCES problems(id), category_id BIGINT REFERENCES categories(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_users(id), message TEXT NOT NULL, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY, actor_id BIGINT REFERENCES app_users(id), action VARCHAR(60) NOT NULL, entity VARCHAR(60) NOT NULL, entity_id BIGINT, details TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_incident_status ON incidents(status,created_at);
CREATE INDEX idx_incident_assignee ON incidents(assignee_id);
CREATE INDEX idx_incident_requester ON incidents(requester_id);
CREATE INDEX idx_incident_category ON incidents(category_id);
CREATE INDEX idx_problem_status ON problems(status,created_at);
CREATE INDEX idx_history_incident ON incident_history(incident_id,created_at);
CREATE INDEX idx_known_error_problem ON known_errors(problem_id);
CREATE INDEX idx_notification_user ON notifications(user_id,created_at);
INSERT INTO roles(name) VALUES ('ADMIN'),('SERVICE_DESK'),('TECHNICIAN'),('INCIDENT_MANAGER'),('PROBLEM_MANAGER'),('USER');
